namespace WinBGMuter.Actions
{
    internal sealed class PauseAction
    {
        private readonly IMediaController _mediaController;
        private readonly SessionResolver _resolver;

        public PauseAction(IMediaController mediaController, SessionResolver resolver)
        {
            _mediaController = mediaController;
            _resolver = resolver;
        }

        public async Task<PauseActionResult> TryPauseAsync(string processName, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();

            var resolution = await _resolver.ResolveAsync(processName, cancellationToken).ConfigureAwait(false);

            switch (resolution.Status)
            {
                case SessionResolutionStatus.NotFound:
                    LoggingEngine.LogLine($"[PauseAction] No session found for {processName}", category: LoggingEngine.LogCategory.MediaControl);
                    return new PauseActionResult(PauseResult.NotSupported, null);

                case SessionResolutionStatus.Ambiguous:
                    LoggingEngine.LogLine($"[PauseAction] Ambiguous session for {processName}", category: LoggingEngine.LogCategory.MediaControl);
                    return new PauseActionResult(PauseResult.Ambiguous, null);

                case SessionResolutionStatus.Success:
                    break;

                default:
                    return new PauseActionResult(PauseResult.Failed, null);
            }

            var session = resolution.Session!;
            var result = await _mediaController.TryPauseAsync(session, cancellationToken).ConfigureAwait(false);

            var pauseResult = result switch
            {
                MediaControlResult.Success => PauseResult.Success,
                MediaControlResult.NotSupported => PauseResult.NotSupported,
                _ => PauseResult.Failed
            };

            return new PauseActionResult(pauseResult, pauseResult == PauseResult.Success ? session : null);
        }

        public async Task<PauseResult> TryResumeAsync(MediaSessionKey sessionKey, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();

            var result = await _mediaController.TryPlayAsync(sessionKey, cancellationToken).ConfigureAwait(false);

            return result switch
            {
                MediaControlResult.Success => PauseResult.Success,
                MediaControlResult.NotSupported => PauseResult.NotSupported,
                _ => PauseResult.Failed
            };
        }
    }

    internal enum PauseResult
    {
        Success,
        NotSupported,
        Ambiguous,
        Failed
    }

    internal readonly struct PauseActionResult
    {
        public PauseActionResult(PauseResult result, MediaSessionKey? sessionKey)
        {
            Result = result;
            SessionKey = sessionKey;
        }

        public PauseResult Result { get; }
        public MediaSessionKey? SessionKey { get; }
    }
}

using WinBGMuter.Abstractions;

namespace WinBGMuter.Audio
{
    internal sealed class AudibilityDetector
    {
        private readonly float _peakThreshold;

        public AudibilityDetector(float peakThreshold)
        {
            _peakThreshold = peakThreshold;
        }

        /// <summary>
        /// Returns the set of PIDs considered audible from a snapshot.
        /// </summary>
        public IReadOnlyList<int> GetAudiblePids(AudioSessionSnapshot snapshot)
        {
            var audible = new List<int>();
            foreach (var p in snapshot.Processes)
            {
                if (IsAudible(p))
                {
                    audible.Add(p.Pid);
                }
            }

            return audible;
        }

        private bool IsAudible(AudioProcessState state)
        {
            // First cut: active & peak above threshold
            return state.IsActive && state.Peak >= _peakThreshold;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Threading;
using System.Threading.Tasks;
using WinBGMuter.Abstractions;

namespace WinBGMuter.Audio
{
    internal sealed class CoreAudioSessionScanner : IAudioSessionScanner
    {
        public Task<AudioSessionSnapshot> GetSnapshotAsync(CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();

            var processes = new List<AudioProcessState>();
            var timestamp = DateTimeOffset.UtcNow;

            IMMDeviceEnumerator deviceEnumerator = null!;
            IMMDevice speakers = null!;
            IAudioSessionManager2 mgr = null!;
            IAudioSessionEnumerator? sessionEnum = null;

            try
            {
                deviceEnumerator = (IMMDeviceEnumerator)new MMDeviceEnumerator();
                deviceEnumerator.GetDefaultAudioEndpoint(EDataFlow.eRender, ERole.eMultimedia, out speakers);

                var iid = typeof(IAudioSessionManager2).GUID;
                speakers.Activate(ref iid, 0, IntPtr.Zero, out var o);
                mgr = (IAudioSessionManager2)o;

                mgr.GetSessionEnumerator(out sessionEnum);
                if (sessionEnum == null)
                {
                    return Task.FromResult(new AudioSessionSnapshot(timestamp, processes));
                }

                sessionEnum.GetCount(out var count);
                for (int i = 0; i < count; i++)
                {
                    sessionEnum.GetSession(i, out IAudioSessionControl2 ctl);
                    ctl.GetProcessId(out var pid);

                    // pid can be 0 for system sounds; skip
                    if (pid == 0)
                    {
                        Marshal.ReleaseComObject(ctl);
                        continue;
                    }

                    string processName = "<unknown>";
                    try
                    {
                        processName = Process.GetProcessById(pid).ProcessName;
                    }
                    catch
                    {
                        // best-effort; keep unknown
                    }

                    bool isActive = false;
                    float peak = 0;

                    // ISimpleAudioVolume also implements IAudioMeterInformation in many cases; we only have volume here,
                    // so we approximate using GetMute/volume state. Keep fields minimal until audibility heuristic (Commit 07).
                    if (ctl is ISimpleAudioVolume vol)
                    {
                        vol.GetMute(out var muted);
                        isActive = !muted;
                    }

                    processes.Add(new AudioProcessState(pid, processName, isActive, peak, timestamp));
                    Marshal.ReleaseComObject(ctl);
                }
            }
            catch (Exception ex)
            {
                LoggingEngine.LogLine($"[AudioSessionScanner] enumeration failed: {ex.Message}", loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING, category: LoggingEngine.LogCategory.AudioSessions);
            }
            finally
            {
                if (sessionEnum != null) Marshal.ReleaseComObject(sessionEnum);
                if (mgr != null) Marshal.ReleaseComObject(mgr);
                if (speakers != null) Marshal.ReleaseComObject(speakers);
                if (deviceEnumerator != null) Marshal.ReleaseComObject(deviceEnumerator);
            }

            return Task.FromResult(new AudioSessionSnapshot(timestamp, processes));
        }
    }
}

using System;
using System.Collections.Concurrent;
using System.IO;
using System.IO.Pipes;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

namespace WinBGMuter.Browser
{
    /// <summary>
    /// Coordinates browser media control across multiple extension instances (profiles).
    /// Runs as a named pipe server in the main app.
    /// </summary>
    internal sealed class BrowserCoordinator : IDisposable
    {
        private const string PipeName = "BackgroundMuter_BrowserCoordinator";
        private readonly CancellationTokenSource _cts = new();
        private readonly ConcurrentDictionary<string, ConnectedExtension> _extensions = new();
        private readonly ConcurrentDictionary<string, ConcurrentDictionary<int, bool>> _extensionTabStates = new();
        private Task? _serverTask;
        private bool _disposed;

        public event EventHandler<BrowserFocusChangedEventArgs>? BrowserFocusChanged;
        public bool IsAnyTabPlaying => HasAnyPlayingTab();

        /// <summary>
        /// Start the named pipe server to accept extension connections.
        /// </summary>
        public void Start()
        {
            if (_serverTask != null) return;
            _serverTask = Task.Run(RunServerAsync);
            LoggingEngine.LogLine("[BrowserCoordinator] Started pipe server",
                category: LoggingEngine.LogCategory.MediaControl);
        }

        public void Stop()
        {
            _cts.Cancel();
            _serverTask?.Wait(2000);
        }

        private async Task RunServerAsync()
        {
            while (!_cts.Token.IsCancellationRequested)
            {
                try
                {
                    var pipe = new NamedPipeServerStream(
                        PipeName,
                        PipeDirection.InOut,
                        NamedPipeServerStream.MaxAllowedServerInstances,
                        PipeTransmissionMode.Byte,
                        PipeOptions.Asynchronous);

                    await pipe.WaitForConnectionAsync(_cts.Token);

                    var extensionId = Guid.NewGuid().ToString();
                    var extension = new ConnectedExtension(extensionId, pipe, this);
                    _extensions.TryAdd(extensionId, extension);
                    _extensionTabStates.TryAdd(extensionId, new ConcurrentDictionary<int, bool>());

                    LoggingEngine.LogLine($"[BrowserCoordinator] Extension connected: {extensionId}",
                        category: LoggingEngine.LogCategory.MediaControl);

                    _ = extension.StartAsync(_cts.Token);
                }
                catch (OperationCanceledException)
                {
                    break;
                }
                catch (Exception ex)
                {
                    LoggingEngine.LogLine($"[BrowserCoordinator] Server error: {ex.Message}",
                        category: LoggingEngine.LogCategory.MediaControl,
                        loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                }
            }
        }

        /// <summary>
        /// Called when the main app detects a foreground window change to a browser.
        /// </summary>
        public void OnBrowserWindowFocused(string windowTitle, IntPtr windowHandle)
        {
            LoggingEngine.LogLine($"[BrowserCoordinator] Browser window focused: {windowTitle}",
                category: LoggingEngine.LogCategory.MediaControl);

            // Tell all extensions about the focus change
            // Each extension will determine if it owns this window
            var message = JsonSerializer.Serialize(new
            {
                action = "browserWindowFocused",
                windowTitle,
                windowHandle = windowHandle.ToInt64()
            });

            BroadcastToExtensions(message);
        }

        /// <summary>
        /// Pause all media across all connected extensions.
        /// </summary>
        public void PauseAllExtensions()
        {
            var message = JsonSerializer.Serialize(new { action = "pauseAll" });
            BroadcastToExtensions(message);
        }

        /// <summary>
        /// Tell extensions to pause all except the one that owns the given window.
        /// </summary>
        public void PauseAllExceptFocused(string focusedWindowTitle)
        {
            var message = JsonSerializer.Serialize(new
            {
                action = "pauseAllExceptFocused",
                focusedWindowTitle
            });
            BroadcastToExtensions(message);
        }

        private void BroadcastToExtensions(string message)
        {
            foreach (var ext in _extensions.Values)
            {
                try
                {
                    ext.SendMessage(message);
                }
                catch (Exception ex)
                {
                    LoggingEngine.LogLine($"[BrowserCoordinator] Failed to send to extension: {ex.Message}",
                        category: LoggingEngine.LogCategory.MediaControl,
                        loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                }
            }
        }

        internal void OnExtensionDisconnected(string extensionId)
        {
            _extensions.TryRemove(extensionId, out _);
            _extensionTabStates.TryRemove(extensionId, out _);
            LoggingEngine.LogLine($"[BrowserCoordinator] Extension disconnected: {extensionId}",
                category: LoggingEngine.LogCategory.MediaControl);
        }

        internal void OnExtensionMessage(string extensionId, string message)
        {
            try
            {
                using var doc = JsonDocument.Parse(message);
                var root = doc.RootElement;

                if (root.TryGetProperty("type", out var typeEl))
                {
                    var type = typeEl.GetString();

                    if (type == "browserLostFocus")
                    {
                        LoggingEngine.LogLine($"[BrowserCoordinator] Extension {extensionId} lost focus",
                            category: LoggingEngine.LogCategory.MediaControl);
                    }
                    else if (type == "mediaStateChanged")
                    {
                        if (TryGetInt(root, out var tabId, "tabId", "TabId") &&
                            TryGetBool(root, out var playing, "playing", "IsPlaying"))
                        {
                            UpdateExtensionTabState(extensionId, tabId, playing);
                        }
                    }
                    else if (type == "tabStates")
                    {
                        if (root.TryGetProperty("tabs", out var tabsElement) &&
                            tabsElement.ValueKind == JsonValueKind.Array)
                        {
                            var updated = new ConcurrentDictionary<int, bool>();
                            foreach (var tab in tabsElement.EnumerateArray())
                            {
                                if (TryGetInt(tab, out var tabId, "tabId", "TabId") &&
                                    TryGetBool(tab, out var playing, "playing", "IsPlaying"))
                                {
                                    updated[tabId] = playing;
                                }
                            }

                            _extensionTabStates.AddOrUpdate(extensionId, updated, (_, __) => updated);
                        }
                    }
                    else if (type == "tabClosed")
                    {
                        if (TryGetInt(root, out var tabId, "tabId", "TabId"))
                        {
                            if (_extensionTabStates.TryGetValue(extensionId, out var tabs))
                            {
                                tabs.TryRemove(tabId, out _);
                            }
                        }
                    }
                    else if (type == "windowFocused")
                    {
                        var title = root.TryGetProperty("title", out var titleEl) ? titleEl.GetString() : "";
                        LoggingEngine.LogLine($"[BrowserCoordinator] Extension {extensionId} focused: {title}",
                            category: LoggingEngine.LogCategory.MediaControl);

                        // This profile gained focus, pause all others
                        PauseAllExceptExtension(extensionId);
                    }
                }
            }
            catch (Exception ex)
            {
                LoggingEngine.LogLine($"[BrowserCoordinator] Error parsing message: {ex.Message}",
                    category: LoggingEngine.LogCategory.MediaControl,
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
            }
        }

        private void PauseAllExceptExtension(string exceptExtensionId)
        {
            var message = JsonSerializer.Serialize(new { action = "pauseAll" });
            foreach (var kvp in _extensions)
            {
                if (kvp.Key != exceptExtensionId)
                {
                    try
                    {
                        kvp.Value.SendMessage(message);
                    }
                    catch { }
                }
            }
        }

        private void UpdateExtensionTabState(string extensionId, int tabId, bool isPlaying)
        {
            var tabs = _extensionTabStates.GetOrAdd(extensionId, _ => new ConcurrentDictionary<int, bool>());
            tabs[tabId] = isPlaying;
        }

        private bool HasAnyPlayingTab()
        {
            foreach (var extension in _extensionTabStates.Values)
            {
                foreach (var isPlaying in extension.Values)
                {
                    if (isPlaying)
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private static bool TryGetInt(JsonElement element, out int value, params string[] names)
        {
            foreach (var name in names)
            {
                if (element.TryGetProperty(name, out var el) && el.TryGetInt32(out value))
                {
                    return true;
                }
            }

            value = 0;
            return false;
        }

        private static bool TryGetBool(JsonElement element, out bool value, params string[] names)
        {
            foreach (var name in names)
            {
                if (element.TryGetProperty(name, out var el) &&
                    (el.ValueKind == JsonValueKind.True || el.ValueKind == JsonValueKind.False))
                {
                    value = el.GetBoolean();
                    return true;
                }
            }

            value = false;
            return false;
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _cts.Cancel();

            foreach (var ext in _extensions.Values)
            {
                ext.Dispose();
            }
            _extensions.Clear();
        }

        private sealed class ConnectedExtension : IDisposable
        {
            private readonly string _id;
            private readonly NamedPipeServerStream _pipe;
            private readonly BrowserCoordinator _coordinator;
            private readonly StreamReader _reader;
            private readonly StreamWriter _writer;
            private readonly SemaphoreSlim _writeLock = new(1, 1);

            public ConnectedExtension(string id, NamedPipeServerStream pipe, BrowserCoordinator coordinator)
            {
                _id = id;
                _pipe = pipe;
                _coordinator = coordinator;
                _reader = new StreamReader(pipe, Encoding.UTF8);
                _writer = new StreamWriter(pipe, Encoding.UTF8) { AutoFlush = true };
            }

            public async Task StartAsync(CancellationToken ct)
            {
                try
                {
                    while (!ct.IsCancellationRequested && _pipe.IsConnected)
                    {
                        var line = await _reader.ReadLineAsync();
                        if (line == null) break;

                        _coordinator.OnExtensionMessage(_id, line);
                    }
                }
                catch (Exception ex)
                {
                    LoggingEngine.LogLine($"[BrowserCoordinator] Extension read error: {ex.Message}",
                        category: LoggingEngine.LogCategory.MediaControl,
                        loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                }
                finally
                {
                    _coordinator.OnExtensionDisconnected(_id);
                    Dispose();
                }
            }

            public void SendMessage(string message)
            {
                _writeLock.Wait();
                try
                {
                    if (_pipe.IsConnected)
                    {
                        _writer.WriteLine(message);
                    }
                }
                finally
                {
                    _writeLock.Release();
                }
            }

            public void Dispose()
            {
                _reader.Dispose();
                _writer.Dispose();
                _pipe.Dispose();
                _writeLock.Dispose();
            }
        }
    }

    internal sealed class BrowserFocusChangedEventArgs : EventArgs
    {
        public string ExtensionId { get; init; } = "";
        public string WindowTitle { get; init; } = "";
        public bool HasFocus { get; init; }
    }
}

using System;
using System.IO;
using System.IO.Pipes;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

namespace WinBGMuter.Browser
{
    /// <summary>
    /// Client that connects to the BrowserCoordinator pipe server.
    /// Used by native messaging host instances to forward messages to the main app.
    /// </summary>
    internal sealed class BrowserCoordinatorClient : IDisposable
    {
        private const string PipeName = "BackgroundMuter_BrowserCoordinator";
        private NamedPipeClientStream? _pipe;
        private StreamReader? _reader;
        private StreamWriter? _writer;
        private readonly CancellationTokenSource _cts = new();
        private Task? _readTask;
        private bool _disposed;

        public event EventHandler<string>? MessageReceived;
        public event EventHandler? Disconnected;

        public bool IsConnected => _pipe?.IsConnected ?? false;

        public bool TryConnect(int timeoutMs = 1000)
        {
            try
            {
                _pipe = new NamedPipeClientStream(".", PipeName, PipeDirection.InOut, PipeOptions.Asynchronous);
                _pipe.Connect(timeoutMs);

                _reader = new StreamReader(_pipe, Encoding.UTF8);
                _writer = new StreamWriter(_pipe, Encoding.UTF8) { AutoFlush = true };

                _readTask = Task.Run(ReadMessagesAsync);

                LoggingEngine.LogLine("[CoordinatorClient] Connected to main app",
                    category: LoggingEngine.LogCategory.MediaControl);
                return true;
            }
            catch (TimeoutException)
            {
                LoggingEngine.LogLine("[CoordinatorClient] Connection timed out - main app not running?",
                    category: LoggingEngine.LogCategory.MediaControl,
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                return false;
            }
            catch (Exception ex)
            {
                LoggingEngine.LogLine($"[CoordinatorClient] Connection failed: {ex.Message}",
                    category: LoggingEngine.LogCategory.MediaControl,
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                return false;
            }
        }

        private async Task ReadMessagesAsync()
        {
            try
            {
                while (!_cts.Token.IsCancellationRequested && _pipe?.IsConnected == true)
                {
                    var line = await _reader!.ReadLineAsync();
                    if (line == null) break;

                    MessageReceived?.Invoke(this, line);
                }
            }
            catch (Exception ex)
            {
                LoggingEngine.LogLine($"[CoordinatorClient] Read error: {ex.Message}",
                    category: LoggingEngine.LogCategory.MediaControl,
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
            }
            finally
            {
                Disconnected?.Invoke(this, EventArgs.Empty);
            }
        }

        public void SendMessage(object message)
        {
            if (_pipe?.IsConnected != true || _writer == null) return;

            try
            {
                var json = JsonSerializer.Serialize(message);
                _writer.WriteLine(json);
            }
            catch (Exception ex)
            {
                LoggingEngine.LogLine($"[CoordinatorClient] Send failed: {ex.Message}",
                    category: LoggingEngine.LogCategory.MediaControl,
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
            }
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;

            _cts.Cancel();
            _reader?.Dispose();
            _writer?.Dispose();
            _pipe?.Dispose();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace WinBGMuter.Browser
{
    /// <summary>
    /// High-level controller for managing browser tab media playback.
    /// Integrates with the native messaging host to send pause/play commands to specific tabs.
    /// </summary>
    internal sealed class BrowserTabController : IDisposable
    {
        private readonly NativeMessagingHost _nativeHost;
        private int _lastActiveTabId = -1;
        private int _lastActiveWindowId = -1;
        private bool _disposed;

        public BrowserTabController()
        {
            _nativeHost = new NativeMessagingHost();
            _nativeHost.TabActivated += OnTabActivated;
            _nativeHost.WindowFocused += OnWindowFocused;
            _nativeHost.TabStateChanged += OnTabStateChanged;
        }

        /// <summary>
        /// Start listening for browser extension messages.
        /// </summary>
        public void Start()
        {
            _nativeHost.Start();
        }

        /// <summary>
        /// Stop listening for browser extension messages.
        /// </summary>
        public void Stop()
        {
            _nativeHost.Stop();
        }

        private void OnTabActivated(object? sender, TabActivatedEventArgs e)
        {
            // When user switches to a different tab in the same window,
            // pause media in the previously active tab
            if (_lastActiveWindowId == e.WindowId && _lastActiveTabId != e.TabId && _lastActiveTabId != -1)
            {
                LoggingEngine.LogLine($"[BrowserTabController] Tab switch in window {e.WindowId}: {_lastActiveTabId} -> {e.TabId}",
                    category: LoggingEngine.LogCategory.MediaControl);

                // Check if the previous tab was playing
                var tabs = _nativeHost.GetTabs();
                if (tabs.TryGetValue(_lastActiveTabId, out var prevTab) && prevTab.IsPlaying)
                {
                    LoggingEngine.LogLine($"[BrowserTabController] Pausing previous tab: {_lastActiveTabId} ({prevTab.Title})",
                        category: LoggingEngine.LogCategory.MediaControl);
                    _nativeHost.SendPauseTab(_lastActiveTabId);
                }
            }

            _lastActiveTabId = e.TabId;
            _lastActiveWindowId = e.WindowId;
        }

        private void OnWindowFocused(object? sender, WindowFocusedEventArgs e)
        {
            // When user switches to a different browser window,
            // pause media in all tabs of the previous window (we track by tab ID)
            if (_lastActiveTabId != -1 && _lastActiveTabId != e.TabId)
            {
                var tabs = _nativeHost.GetTabs();
                if (tabs.TryGetValue(_lastActiveTabId, out var prevTab) && prevTab.IsPlaying)
                {
                    LoggingEngine.LogLine($"[BrowserTabController] Window switch: pausing tab {_lastActiveTabId} ({prevTab.Title})",
                        category: LoggingEngine.LogCategory.MediaControl);
                    _nativeHost.SendPauseTab(_lastActiveTabId);
                }
            }

            _lastActiveTabId = e.TabId;
            _lastActiveWindowId = e.WindowId;
        }

        private void OnTabStateChanged(object? sender, TabStateChangedEventArgs e)
        {
            LoggingEngine.LogLine($"[BrowserTabController] Tab {e.TabId} state changed: {(e.IsPlaying ? "playing" : "paused")} - {e.Title}",
                category: LoggingEngine.LogCategory.MediaControl);
        }

        /// <summary>
        /// Pause all browser tabs that are currently playing media.
        /// </summary>
        public void PauseAllTabs()
        {
            foreach (var tab in _nativeHost.GetPlayingTabs())
            {
                _nativeHost.SendPauseTab(tab.TabId);
            }
        }

        /// <summary>
        /// Pause all browser tabs except the specified one.
        /// </summary>
        public void PauseAllTabsExcept(int exceptTabId)
        {
            _nativeHost.SendPauseAllExcept(exceptTabId);
        }

        /// <summary>
        /// Get all tabs that are currently playing media.
        /// </summary>
        public IEnumerable<TabInfo> GetPlayingTabs()
        {
            return _nativeHost.GetPlayingTabs();
        }

        /// <summary>
        /// Check if any browser tab is currently playing media.
        /// </summary>
        public bool IsAnyTabPlaying()
        {
            return _nativeHost.GetPlayingTabs().Any();
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _nativeHost.Dispose();
        }
    }
}

using System;
using System.Collections.Concurrent;
using System.IO;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

namespace WinBGMuter.Browser
{
    /// <summary>
    /// Handles native messaging communication with browser extensions.
    /// Uses stdin/stdout for message passing as per Chrome Native Messaging protocol.
    /// </summary>
    internal sealed class NativeMessagingHost : IDisposable
    {
        private const int MaxMessageSize = 1024 * 1024; // 1MB max
        private readonly CancellationTokenSource _cts = new();
        private readonly ConcurrentDictionary<int, TabInfo> _tabs = new();
        private Task? _readTask;
        private bool _disposed;

        public event EventHandler<TabStateChangedEventArgs>? TabStateChanged;
        public event EventHandler<TabActivatedEventArgs>? TabActivated;
        public event EventHandler<WindowFocusedEventArgs>? WindowFocused;
        public event EventHandler? BrowserLostFocus;

        public void Start()
        {
            if (_readTask != null) return;

            _readTask = Task.Run(ReadMessagesAsync, _cts.Token);
            LoggingEngine.LogLine("[NativeMessaging] Host started, listening for browser messages",
                category: LoggingEngine.LogCategory.MediaControl);
        }

        public void Stop()
        {
            _cts.Cancel();
            _readTask?.Wait(1000);
        }

        public void WaitForExit()
        {
            _readTask?.Wait();
        }

        private async Task ReadMessagesAsync()
        {
            using var stdin = Console.OpenStandardInput();
            var buffer = new byte[4];

            while (!_cts.Token.IsCancellationRequested)
            {
                try
                {
                    // Read message length (4 bytes, little-endian)
                    var bytesRead = await ReadExactlyAsync(stdin, buffer, 0, buffer.Length, _cts.Token).ConfigureAwait(false);
                    if (bytesRead == 0)
                    {
                        break; // EOF
                    }
                    if (bytesRead < buffer.Length)
                    {
                        LoggingEngine.LogLine("[NativeMessaging] Incomplete message length received, closing host",
                            category: LoggingEngine.LogCategory.MediaControl,
                            loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                        break;
                    }

                    int messageLength = BitConverter.ToInt32(buffer, 0);
                    if (messageLength <= 0 || messageLength > MaxMessageSize)
                    {
                        LoggingEngine.LogLine($"[NativeMessaging] Invalid message length {messageLength}, closing host",
                            category: LoggingEngine.LogCategory.MediaControl,
                            loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                        break;
                    }

                    // Read message content
                    var messageBuffer = new byte[messageLength];
                    bytesRead = await ReadExactlyAsync(stdin, messageBuffer, 0, messageLength, _cts.Token).ConfigureAwait(false);
                    if (bytesRead < messageLength)
                    {
                        LoggingEngine.LogLine("[NativeMessaging] Incomplete message payload received, closing host",
                            category: LoggingEngine.LogCategory.MediaControl,
                            loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                        break;
                    }

                    var json = Encoding.UTF8.GetString(messageBuffer);
                    ProcessMessage(json);
                }
                catch (OperationCanceledException)
                {
                    break;
                }
                catch (Exception ex)
                {
                    LoggingEngine.LogLine($"[NativeMessaging] Error reading message: {ex.Message}",
                        category: LoggingEngine.LogCategory.MediaControl,
                        loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                }
            }
        }

        private static async Task<int> ReadExactlyAsync(Stream stream, byte[] buffer, int offset, int count, CancellationToken ct)
        {
            int totalRead = 0;
            while (totalRead < count)
            {
                int read = await stream.ReadAsync(buffer.AsMemory(offset + totalRead, count - totalRead), ct).ConfigureAwait(false);
                if (read == 0)
                {
                    return totalRead;
                }
                totalRead += read;
            }

            return totalRead;
        }

        private void ProcessMessage(string json)
        {
            try
            {
                using var doc = JsonDocument.Parse(json);
                var root = doc.RootElement;

                if (!root.TryGetProperty("type", out var typeElement))
                {
                    return;
                }

                var type = typeElement.GetString();

                switch (type)
                {
                    case "mediaStateChanged":
                        HandleMediaStateChanged(root);
                        break;
                    case "tabActivated":
                        HandleTabActivated(root);
                        break;
                    case "windowFocused":
                        HandleWindowFocused(root);
                        break;
                    case "browserLostFocus":
                        BrowserLostFocus?.Invoke(this, EventArgs.Empty);
                        break;
                    case "tabClosed":
                        HandleTabClosed(root);
                        break;
                    case "tabStates":
                        HandleTabStates(root);
                        break;
                }
            }
            catch (Exception ex)
            {
                LoggingEngine.LogLine($"[NativeMessaging] Error processing message: {ex.Message}",
                    category: LoggingEngine.LogCategory.MediaControl,
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
            }
        }

        private void HandleMediaStateChanged(JsonElement root)
        {
            var tabId = root.GetProperty("tabId").GetInt32();
            var playing = root.GetProperty("playing").GetBoolean();
            var title = root.TryGetProperty("title", out var t) ? t.GetString() ?? "" : "";
            var url = root.TryGetProperty("url", out var u) ? u.GetString() ?? "" : "";

            _tabs[tabId] = new TabInfo(tabId, playing, title, url);

            LoggingEngine.LogLine($"[NativeMessaging] Tab {tabId} media state: {(playing ? "playing" : "paused")} - {title}",
                category: LoggingEngine.LogCategory.MediaControl);

            TabStateChanged?.Invoke(this, new TabStateChangedEventArgs(tabId, playing, title, url));
        }

        private void HandleTabActivated(JsonElement root)
        {
            var tabId = root.GetProperty("tabId").GetInt32();
            var windowId = root.GetProperty("windowId").GetInt32();
            var title = root.TryGetProperty("title", out var t) ? t.GetString() ?? "" : "";

            LoggingEngine.LogLine($"[NativeMessaging] Tab activated: {tabId} in window {windowId} - {title}",
                category: LoggingEngine.LogCategory.MediaControl);

            TabActivated?.Invoke(this, new TabActivatedEventArgs(tabId, windowId, title));
        }

        private void HandleWindowFocused(JsonElement root)
        {
            var windowId = root.GetProperty("windowId").GetInt32();
            var tabId = root.GetProperty("tabId").GetInt32();
            var title = root.TryGetProperty("title", out var t) ? t.GetString() ?? "" : "";

            LoggingEngine.LogLine($"[NativeMessaging] Window focused: {windowId}, active tab: {tabId} - {title}",
                category: LoggingEngine.LogCategory.MediaControl);

            WindowFocused?.Invoke(this, new WindowFocusedEventArgs(windowId, tabId, title));
        }

        private void HandleTabClosed(JsonElement root)
        {
            var tabId = root.GetProperty("tabId").GetInt32();
            _tabs.TryRemove(tabId, out var removed);

            LoggingEngine.LogLine($"[NativeMessaging] Tab closed: {tabId}",
                category: LoggingEngine.LogCategory.MediaControl);

            var title = removed?.Title ?? string.Empty;
            var url = removed?.Url ?? string.Empty;
            TabStateChanged?.Invoke(this, new TabStateChangedEventArgs(tabId, false, title, url));
        }

        private void HandleTabStates(JsonElement root)
        {
            if (!root.TryGetProperty("tabs", out var tabsArray))
            {
                return;
            }

            _tabs.Clear();
            foreach (var tab in tabsArray.EnumerateArray())
            {
                var tabId = tab.GetProperty("tabId").GetInt32();
                var playing = tab.GetProperty("playing").GetBoolean();
                var title = tab.TryGetProperty("title", out var t) ? t.GetString() ?? "" : "";
                var url = tab.TryGetProperty("url", out var u) ? u.GetString() ?? "" : "";

                _tabs[tabId] = new TabInfo(tabId, playing, title, url);
            }

            LoggingEngine.LogLine($"[NativeMessaging] Received {_tabs.Count} tab states",
                category: LoggingEngine.LogCategory.MediaControl);

            foreach (var tab in _tabs.Values)
            {
                TabStateChanged?.Invoke(this, new TabStateChangedEventArgs(tab.TabId, tab.IsPlaying, tab.Title, tab.Url));
            }
        }

        /// <summary>
        /// Send a command to pause a specific tab.
        /// </summary>
        public void SendPauseTab(int tabId)
        {
            SendMessage(new { action = "pauseTab", tabId = tabId });
        }

        /// <summary>
        /// Send a command to play a specific tab.
        /// </summary>
        public void SendPlayTab(int tabId)
        {
            SendMessage(new { action = "playTab", tabId = tabId });
        }

        /// <summary>
        /// Send a command to pause all tabs except the specified one.
        /// </summary>
        public void SendPauseAllExcept(int exceptTabId)
        {
            SendMessage(new { action = "pauseAllExcept", tabId = exceptTabId });
        }

        /// <summary>
        /// Request current tab states from the extension.
        /// </summary>
        public void RequestTabStates()
        {
            SendMessage(new { action = "getTabStates" });
        }

        private void SendMessage(object message)
        {
            var json = JsonSerializer.Serialize(message);
            SendRawMessage(json);
        }

        /// <summary>
        /// Send a raw JSON message to the extension via stdout.
        /// </summary>
        public void SendRawMessage(string json)
        {
            try
            {
                var bytes = Encoding.UTF8.GetBytes(json);
                var lengthBytes = BitConverter.GetBytes(bytes.Length);

                using var stdout = Console.OpenStandardOutput();
                stdout.Write(lengthBytes, 0, 4);
                stdout.Write(bytes, 0, bytes.Length);
                stdout.Flush();

                LoggingEngine.LogLine($"[NativeMessaging] Sent: {json}",
                    category: LoggingEngine.LogCategory.MediaControl);
            }
            catch (Exception ex)
            {
                LoggingEngine.LogLine($"[NativeMessaging] Error sending message: {ex.Message}",
                    category: LoggingEngine.LogCategory.MediaControl,
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
            }
        }

        /// <summary>
        /// Get all known tabs with their current states.
        /// </summary>
        public IReadOnlyDictionary<int, TabInfo> GetTabs() => _tabs;

        /// <summary>
        /// Get tabs that are currently playing media.
        /// </summary>
        public IEnumerable<TabInfo> GetPlayingTabs()
        {
            foreach (var tab in _tabs.Values)
            {
                if (tab.IsPlaying)
                {
                    yield return tab;
                }
            }
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            Stop();
            _cts.Dispose();
        }
    }

    internal sealed record TabInfo(int TabId, bool IsPlaying, string Title, string Url);

    internal sealed class TabStateChangedEventArgs : EventArgs
    {
        public int TabId { get; }
        public bool IsPlaying { get; }
        public string Title { get; }
        public string Url { get; }

        public TabStateChangedEventArgs(int tabId, bool isPlaying, string title, string url)
        {
            TabId = tabId;
            IsPlaying = isPlaying;
            Title = title;
            Url = url;
        }
    }

    internal sealed class TabActivatedEventArgs : EventArgs
    {
        public int TabId { get; }
        public int WindowId { get; }
        public string Title { get; }

        public TabActivatedEventArgs(int tabId, int windowId, string title)
        {
            TabId = tabId;
            WindowId = windowId;
            Title = title;
        }
    }

    internal sealed class WindowFocusedEventArgs : EventArgs
    {
        public int WindowId { get; }
        public int TabId { get; }
        public string Title { get; }

        public WindowFocusedEventArgs(int windowId, int tabId, string title)
        {
            WindowId = windowId;
            TabId = tabId;
            Title = title;
        }
    }
}

using WinBGMuter.Abstractions;

namespace WinBGMuter.Config
{
    internal sealed class PauseOnUnfocusSettings
    {
        private const string SettingKeyEnabled = "PauseOnUnfocusEnabled";
        private const string SettingKeyMode = "PauseOnUnfocusMode";
        private const string SettingKeyAudibilityThreshold = "AudibilityThreshold";
        private const string SettingKeyPauseCooldownMs = "PauseCooldownMs";

        public bool Enabled { get; set; } = false;
        public PolicyMode Mode { get; set; } = PolicyMode.PauseOnly;
        public float AudibilityThreshold { get; set; } = 0.01f;
        public int PauseCooldownMs { get; set; } = 7000;

        public void Load()
        {
            try
            {
                Enabled = Properties.Settings.Default[SettingKeyEnabled] as bool? ?? false;
            }
            catch
            {
                Enabled = false;
            }

            try
            {
                var modeValue = Properties.Settings.Default[SettingKeyMode] as int? ?? (int)PolicyMode.PauseOnly;
                Mode = (PolicyMode)modeValue;
            }
            catch
            {
                Mode = PolicyMode.PauseOnly;
            }

            try
            {
                AudibilityThreshold = Properties.Settings.Default[SettingKeyAudibilityThreshold] as float? ?? 0.01f;
            }
            catch
            {
                AudibilityThreshold = 0.01f;
            }

            try
            {
                PauseCooldownMs = Properties.Settings.Default[SettingKeyPauseCooldownMs] as int? ?? 7000;
            }
            catch
            {
                PauseCooldownMs = 7000;
            }
        }

        public void Save()
        {
            try
            {
                Properties.Settings.Default[SettingKeyEnabled] = Enabled;
                Properties.Settings.Default[SettingKeyMode] = (int)Mode;
                Properties.Settings.Default[SettingKeyAudibilityThreshold] = AudibilityThreshold;
                Properties.Settings.Default[SettingKeyPauseCooldownMs] = PauseCooldownMs;
                Properties.Settings.Default.Save();
                SettingsFileStore.Save();
            }
            catch
            {
                // Settings may not exist yet
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text.Json;

namespace WinBGMuter.Config
{
    internal static class SettingsFileStore
    {
        private const string SettingsFileName = "WinBGMuter_settings.json";
        private static string SettingsFilePath => Path.Combine(AppContext.BaseDirectory, SettingsFileName);

        public static void Load()
        {
            try
            {
                EnsureFileExists();

                var json = File.ReadAllText(SettingsFilePath);
                var map = JsonSerializer.Deserialize<Dictionary<string, string?>>(json) ?? new Dictionary<string, string?>();

                var properties = Properties.Settings.Default.Properties.Cast<System.Configuration.SettingsProperty>()
                    .ToDictionary(p => p.Name, StringComparer.OrdinalIgnoreCase);

                foreach (var kvp in map)
                {
                    if (!properties.TryGetValue(kvp.Key, out var prop))
                    {
                        continue;
                    }

                    var converted = ConvertFromString(kvp.Value, prop.PropertyType);
                    if (converted != null)
                    {
                        Properties.Settings.Default[kvp.Key] = converted;
                    }
                }
            }
            catch
            {
                // Swallow read/parse errors to avoid blocking startup; user can still run with defaults.
            }
        }

        public static void Save()
        {
            try
            {
                var map = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

                foreach (System.Configuration.SettingsProperty prop in Properties.Settings.Default.Properties)
                {
                    var value = Properties.Settings.Default[prop.Name];
                    map[prop.Name] = Convert.ToString(value, CultureInfo.InvariantCulture);
                }

                var json = JsonSerializer.Serialize(map, new JsonSerializerOptions
                {
                    WriteIndented = true
                });

                File.WriteAllText(SettingsFilePath, json);
            }
            catch
            {
                // Swallow write errors; app continues without blocking shutdown.
            }
        }

        private static void EnsureFileExists()
        {
            if (!File.Exists(SettingsFilePath))
            {
                Directory.CreateDirectory(Path.GetDirectoryName(SettingsFilePath)!);
                Save();
            }
        }

        private static object? ConvertFromString(string? value, Type targetType)
        {
            if (value == null)
            {
                return null;
            }

            try
            {
                var converter = TypeDescriptor.GetConverter(targetType);
                if (converter.CanConvertFrom(typeof(string)))
                {
                    return converter.ConvertFromString(null, CultureInfo.InvariantCulture, value);
                }
            }
            catch
            {
                // ignore conversion failures
            }

            return null;
        }
    }
}

using System;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;
using WinBGMuter.Abstractions;
using WinBGMuter.Actions;
using WinBGMuter.Audio;
using WinBGMuter.Foreground;
using WinBGMuter.Media;
using WinBGMuter.Policy;
using WinBGMuter.State;

namespace WinBGMuter.Controller
{
    internal sealed class AppController : IDisposable
    {
        private readonly WinEventForegroundTracker _foregroundTracker;
        private readonly VolumeMixer _volumeMixer;
        private readonly GsmtcMediaController _mediaController;
        private readonly SessionResolver _sessionResolver;
        private readonly PauseAction _pauseAction;
        private readonly ActionPolicyEngine _policyEngine;
        private readonly PlaybackStateStore _stateStore;
        private readonly Func<bool>? _isExternalMediaPlaying;

        private bool _enabled = true;
        private bool _autoPlaySpotify = false;
        private string _autoPlayAppName = "Spotify";
        private System.Timers.Timer? _autoPlayMonitorTimer;
        private bool _autoPlayAppPausedByUs = false;
        private int _autoPlayTickInProgress = 0;
        private ForegroundChangedEventArgs? _pendingForegroundEvent;
        private int _foregroundWorkerRunning = 0;

        private Func<IEnumerable<string>>? _getNeverPauseList;
        private int _pauseCooldownMs = 7000;
        private long _cooldownDeadlineMs = 0;

        // Per-window tracking for same-process window switching
        private IntPtr _previousWindowHandle = IntPtr.Zero;
        private int _previousWindowPid = -1;
        private string _previousWindowTitle = string.Empty;

        public AppController(
            VolumeMixer volumeMixer,
            float audibilityThreshold = 0.01f,
            IReadOnlyDictionary<string, string>? processNameToSessionHint = null,
            Func<IEnumerable<string>>? getNeverPauseList = null,
            bool autoPlaySpotify = false,
            string autoPlayAppName = "Spotify",
            int pauseCooldownMs = 7000,
            Func<bool>? isExternalMediaPlaying = null)
        {
            _volumeMixer = volumeMixer;
            _getNeverPauseList = getNeverPauseList;
            _autoPlaySpotify = autoPlaySpotify;
            _autoPlayAppName = autoPlayAppName;
            _pauseCooldownMs = pauseCooldownMs;
            _isExternalMediaPlaying = isExternalMediaPlaying;
            _foregroundTracker = new WinEventForegroundTracker();
            _mediaController = new GsmtcMediaController();
            _sessionResolver = new SessionResolver(_mediaController, processNameToSessionHint);
            _pauseAction = new PauseAction(_mediaController, _sessionResolver);
            _policyEngine = new ActionPolicyEngine();
            _stateStore = new PlaybackStateStore();

            _foregroundTracker.ForegroundChanged += OnForegroundChanged;
        }

        public bool Enabled
        {
            get => _enabled;
            set => _enabled = value;
        }

        public bool AutoPlaySpotify
        {
            get => _autoPlaySpotify;
            set
            {
                _autoPlaySpotify = value;
                if (value)
                {
                    StartAutoPlayMonitor();
                }
                else
                {
                    StopAutoPlayMonitor();
                }
            }
        }

        public string AutoPlayAppName
        {
            get => _autoPlayAppName;
            set => _autoPlayAppName = value;
        }

        public int PauseCooldownMs
        {
            get => _pauseCooldownMs;
            set => _pauseCooldownMs = Math.Max(0, value);
        }

        public void Start()
        {
            _foregroundTracker.Start();
            if (_autoPlaySpotify)
            {
                StartAutoPlayMonitor();
            }
            LoggingEngine.LogLine("[AppController] Started", category: LoggingEngine.LogCategory.General);
        }

        public void Stop()
        {
            _foregroundTracker.Stop();
            StopAutoPlayMonitor();
            LoggingEngine.LogLine("[AppController] Stopped", category: LoggingEngine.LogCategory.General);
        }

        private void StartAutoPlayMonitor()
        {
            if (_autoPlayMonitorTimer != null)
            {
                return;
            }

            _autoPlayMonitorTimer = new System.Timers.Timer(1000); // Check every 1 second
            _autoPlayMonitorTimer.Elapsed += async (s, e) => await OnAutoPlayMonitorTickAsync();
            _autoPlayMonitorTimer.AutoReset = true;
            _autoPlayMonitorTimer.Start();
            LoggingEngine.LogLine($"[AutoPlay] Monitor started for {_autoPlayAppName}", category: LoggingEngine.LogCategory.MediaControl);
        }

        private void StopAutoPlayMonitor()
        {
            if (_autoPlayMonitorTimer == null)
            {
                return;
            }

            _autoPlayMonitorTimer.Stop();
            _autoPlayMonitorTimer.Dispose();
            _autoPlayMonitorTimer = null;
            _autoPlayAppPausedByUs = false;
            LoggingEngine.LogLine("[AutoPlay] Monitor stopped", category: LoggingEngine.LogCategory.MediaControl);
        }

        private async Task OnAutoPlayMonitorTickAsync()
        {
            if (!_autoPlaySpotify || string.IsNullOrWhiteSpace(_autoPlayAppName))
            {
                return;
            }

            if (Interlocked.Exchange(ref _autoPlayTickInProgress, 1) == 1)
            {
                return;
            }

            try
            {
                var sessions = await _mediaController.ListSessionsAsync().ConfigureAwait(false);

                var targetSession = sessions.FirstOrDefault(s => IsTargetAppSession(s));
                if (targetSession == null)
                {
                    return;
                }

                // Check if any other app is currently playing
                var otherPlaying = sessions.Any(s =>
                    s.PlaybackState == MediaPlaybackState.Playing &&
                    !IsTargetAppSession(s));
                var externalPlaying = _isExternalMediaPlaying?.Invoke() ?? false;
                if (externalPlaying)
                {
                    otherPlaying = true;
                }

                if (otherPlaying)
                {
                    ResetCooldownWindow();
                }

                if (otherPlaying)
                {
                    // Another app is playing - pause target app if it's playing
                    if (targetSession.PlaybackState == MediaPlaybackState.Playing)
                    {
                        var result = await _mediaController.TryPauseAsync(targetSession.Key).ConfigureAwait(false);
                        if (result == MediaControlResult.Success)
                        {
                            _autoPlayAppPausedByUs = true;
                            LoggingEngine.LogLine($"[AutoPlay] Paused {_autoPlayAppName} (other app started playing)",
                                category: LoggingEngine.LogCategory.MediaControl);
                        }
                    }
                }
                else
                {
                    // Wait until the cooldown window has been quiet
                    await WaitForCooldownAsync().ConfigureAwait(false);

                    // No other app is playing - resume target app if it's not playing
                    if (targetSession.PlaybackState != MediaPlaybackState.Playing)
                    {
                        var result = await _mediaController.TryPlayAsync(targetSession.Key).ConfigureAwait(false);
                        if (result == MediaControlResult.Success)
                        {
                            _autoPlayAppPausedByUs = false;
                            LoggingEngine.LogLine($"[AutoPlay] Resumed {_autoPlayAppName} (no other app playing)",
                                category: LoggingEngine.LogCategory.MediaControl);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                LoggingEngine.LogLine($"[AutoPlay] Monitor error: {ex.Message}",
                    category: LoggingEngine.LogCategory.MediaControl,
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
            }
            finally
            {
                Interlocked.Exchange(ref _autoPlayTickInProgress, 0);
            }
        }

        private async void OnForegroundChanged(object? sender, ForegroundChangedEventArgs e)
        {
            if (!_enabled)
            {
                return;
            }

            _pendingForegroundEvent = e;
            if (Interlocked.Exchange(ref _foregroundWorkerRunning, 1) == 1)
            {
                return;
            }

            _ = Task.Run(ProcessForegroundQueueAsync);
        }

        private async Task ProcessForegroundQueueAsync()
        {
            try
            {
                while (true)
                {
                    var next = Interlocked.Exchange(ref _pendingForegroundEvent, null);
                    if (next == null)
                    {
                        break;
                    }

                    await ProcessForegroundChangeAsync(next).ConfigureAwait(false);
                }
            }
            catch (Exception ex)
            {
                LoggingEngine.LogLine($"[AppController] Error processing foreground change: {ex.Message}",
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING,
                    category: LoggingEngine.LogCategory.General);
            }
            finally
            {
                Interlocked.Exchange(ref _foregroundWorkerRunning, 0);
                if (_pendingForegroundEvent != null && Interlocked.Exchange(ref _foregroundWorkerRunning, 1) == 0)
                {
                    _ = Task.Run(ProcessForegroundQueueAsync);
                }
            }
        }

        private async Task ProcessForegroundChangeAsync(ForegroundChangedEventArgs e)
        {
            ResetCooldownWindow();
            await WaitForCooldownAsync().ConfigureAwait(false);

            var foregroundPid = e.CurrentPid;
            var foregroundHwnd = e.Hwnd;
            var foregroundTitle = string.IsNullOrWhiteSpace(e.WindowTitle) ? "<no title>" : e.WindowTitle.Trim();
            string foregroundProcessName = "<unknown>";

            try
            {
                foregroundProcessName = Process.GetProcessById(foregroundPid).ProcessName;
            }
            catch
            {
                // Process may have exited
            }

            LoggingEngine.LogLine($"[AppController] Foreground changed to {foregroundProcessName} (PID {foregroundPid}) Title=\"{foregroundTitle}\"",
                category: LoggingEngine.LogCategory.Foreground);

            // Per-window pause: If switching between different windows of the same process,
            // send pause to the previous window (but NOT for browsers - they use extension)
            if (_previousWindowHandle != IntPtr.Zero && 
                _previousWindowHandle != foregroundHwnd &&
                _previousWindowPid == foregroundPid &&
                !IsBrowserProcess(foregroundProcessName))
            {
                LoggingEngine.LogLine($"[AppController] Same-process window switch detected, pausing previous window: {_previousWindowTitle}",
                    category: LoggingEngine.LogCategory.MediaControl);

                Win32MediaCommandController.PostPause(_previousWindowHandle);
            }
            else if (IsBrowserProcess(foregroundProcessName) && _previousWindowHandle != foregroundHwnd)
            {
                LoggingEngine.LogLine($"[AppController] Browser window switch - skipping Win32 pause (extension handles this)",
                    category: LoggingEngine.LogCategory.MediaControl);
            }

            // Update previous window tracking
            _previousWindowHandle = foregroundHwnd;
            _previousWindowPid = foregroundPid;
            _previousWindowTitle = foregroundTitle;

            // 1) Get audio PIDs from VolumeMixer (already works for existing mute logic)
            int[] audioPids = _volumeMixer.GetPIDs();
            var audiblePids = new List<int>(audioPids);

            LoggingEngine.LogLine($"[AppController] Found {audiblePids.Count} audio PIDs: {string.Join(", ", audiblePids)}",
                category: LoggingEngine.LogCategory.Policy);

            // 2) Evaluate policy
            var decision = _policyEngine.Evaluate(foregroundPid, audiblePids, foregroundProcessName);

            LoggingEngine.LogLine($"[AppController] Policy decision: ToPause={decision.ToPause.Count}",
                category: LoggingEngine.LogCategory.Policy);

            // 3) Resume foreground if we paused it
            if (_stateStore.TryGetPaused(foregroundPid, out var pausedState))
            {
                LoggingEngine.LogLine($"[AppController] Resuming {foregroundProcessName} (was paused by us)",
                    category: LoggingEngine.LogCategory.Policy);

                var sessionKey = new MediaSessionKey(pausedState.SessionKey, null);
                var resumeResult = await _pauseAction.TryResumeAsync(sessionKey).ConfigureAwait(false);

                if (resumeResult == PauseResult.Success)
                {
                    _stateStore.Clear(foregroundPid);
                }
            }

            // 4) Pause/mute background apps
            var neverPauseList = _getNeverPauseList?.Invoke()?.ToHashSet(StringComparer.OrdinalIgnoreCase) 
                ?? new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            foreach (var pid in decision.ToPause)
            {
                // Skip PID 0 (system idle process)
                if (pid == 0)
                {
                    continue;
                }

                string processName = GetProcessName(pid);

                // Skip if this is the same app as foreground (handles multi-process apps like browsers)
                if (string.Equals(processName, foregroundProcessName, StringComparison.OrdinalIgnoreCase))
                {
                    LoggingEngine.LogLine($"[AppController] Skipping {processName} PID {pid} (same app as foreground)",
                        category: LoggingEngine.LogCategory.Policy);
                    continue;
                }

                // Skip browsers - they are controlled by the browser extension, not GSMTC
                if (IsBrowserProcess(processName))
                {
                    LoggingEngine.LogLine($"[AppController] Skipping {processName} PID {pid} (browser - controlled by extension)",
                        category: LoggingEngine.LogCategory.Policy);
                    continue;
                }

                // Skip if in never-pause list
                if (neverPauseList.Contains(processName))
                {
                    LoggingEngine.LogLine($"[AppController] Skipping {processName} (in never-pause list)",
                        category: LoggingEngine.LogCategory.Policy);
                    continue;
                }

                var pauseActionResult = await _pauseAction.TryPauseAsync(processName).ConfigureAwait(false);

                if (pauseActionResult.Result == PauseResult.Success && pauseActionResult.SessionKey != null)
                {
                    _stateStore.MarkPaused(pid, "pause", pauseActionResult.SessionKey.Id);
                    LoggingEngine.LogLine($"[AppController] Paused {processName} (session: {pauseActionResult.SessionKey.Id})",
                        category: LoggingEngine.LogCategory.Policy);
                }
                else
                {
                    LoggingEngine.LogLine($"[AppController] Pause not supported for {processName}",
                        category: LoggingEngine.LogCategory.Policy,
                        loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                }
            }

            // 5) Cleanup exited processes
            _stateStore.CleanupExitedProcesses();
        }

        private void ResetCooldownWindow()
        {
            var newDeadline = DateTimeOffset.UtcNow.AddMilliseconds(_pauseCooldownMs).ToUnixTimeMilliseconds();
            Interlocked.Exchange(ref _cooldownDeadlineMs, newDeadline);
        }

        private async Task WaitForCooldownAsync()
        {
            // Wait until deadline has passed with no newer activity.
            // If another activity arrives, its reset pushes the deadline out.
            while (true)
            {
                var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
                var remaining = Interlocked.Read(ref _cooldownDeadlineMs) - nowMs;

                if (remaining <= 0)
                {
                    break;
                }

                // Sleep the smaller of remaining or the cooldown to stay responsive to resets.
                var delay = (int)Math.Min(remaining, _pauseCooldownMs);
                await Task.Delay(delay).ConfigureAwait(false);
            }
        }

        private bool IsTargetAppSession(MediaSessionInfo session)
        {
            var appId = session.AppId?.ToLowerInvariant() ?? string.Empty;
            var displayName = session.DisplayName?.ToLowerInvariant() ?? string.Empty;
            var targetLower = _autoPlayAppName.ToLowerInvariant();
            return appId.Contains(targetLower) || displayName.Contains(targetLower);
        }

        private static string GetProcessName(int pid)
        {
            try
            {
                return Process.GetProcessById(pid).ProcessName;
            }
            catch
            {
                return "<unknown>";
            }
        }

        // Browsers are controlled by the browser extension, not GSMTC
        private static readonly HashSet<string> BrowserProcessNames = new(StringComparer.OrdinalIgnoreCase)
        {
            "msedge",
            "chrome",
            "firefox",
            "brave",
            "opera",
            "vivaldi"
        };

        private static bool IsBrowserProcess(string processName)
        {
            return BrowserProcessNames.Contains(processName);
        }

        public void Dispose()
        {
            StopAutoPlayMonitor();
            _foregroundTracker.ForegroundChanged -= OnForegroundChanged;
            _foregroundTracker.Dispose();
        }
    }
}

using System.Runtime.InteropServices;
using WinBGMuter.Abstractions;

namespace WinBGMuter.Foreground
{
    /// <summary>
    /// WinEvent-based foreground tracker implementing the IForegroundTracker abstraction.
    /// </summary>
    internal sealed class WinEventForegroundTracker : IForegroundTracker
    {
        private const uint EVENT_SYSTEM_FOREGROUND = 0x0003;
        private const int OBJID_WINDOW = 0x00000000;
        private const int CHILDID_SELF = 0;
        private const uint WINEVENT_OUTOFCONTEXT = 0x0000;

        private delegate void WinEventProcDelegate(
            IntPtr hWinEventHook,
            uint @event,
            IntPtr hwnd,
            int idObject,
            int idChild,
            uint dwEventThread,
            uint dwmsEventTime);

        [DllImport("user32.dll", SetLastError = true)]
        private static extern IntPtr SetWinEventHook(
            uint eventMin,
            uint eventMax,
            IntPtr hmodWinEventProc,
            WinEventProcDelegate lpfnWinEventProc,
            uint idProcess,
            uint idThread,
            uint dwFlags);

        [DllImport("user32.dll", SetLastError = true)]
        private static extern bool UnhookWinEvent(IntPtr hWinEventHook);

        [DllImport("user32.dll", SetLastError = true)]
        private static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);

        [DllImport("user32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern int GetWindowText(IntPtr hWnd, System.Text.StringBuilder lpString, int nMaxCount);

        [DllImport("user32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern int GetWindowTextLength(IntPtr hWnd);

        private readonly System.Timers.Timer _debounceTimer;
        private readonly object _sync = new();
        private int _lastPid = -1;
        private IntPtr _lastHwnd = IntPtr.Zero;
        private int _pendingPid = -1;
        private IntPtr _pendingHwnd = IntPtr.Zero;
        private IntPtr _hook = IntPtr.Zero;
        private WinEventProcDelegate? _callback;

        public WinEventForegroundTracker(int debounceIntervalMs = 200)
        {
            _debounceTimer = new System.Timers.Timer(debounceIntervalMs)
            {
                AutoReset = false
            };
            _debounceTimer.Elapsed += DebounceElapsed;
        }

        public event EventHandler<ForegroundChangedEventArgs>? ForegroundChanged;

        public void Start()
        {
            if (_hook != IntPtr.Zero)
            {
                return;
            }

            _callback = WinEventProc;
            _hook = SetWinEventHook(EVENT_SYSTEM_FOREGROUND, EVENT_SYSTEM_FOREGROUND, IntPtr.Zero, _callback, 0, 0, WINEVENT_OUTOFCONTEXT);
        }

        public void Stop()
        {
            if (_hook != IntPtr.Zero)
            {
                UnhookWinEvent(_hook);
                _hook = IntPtr.Zero;
            }
            _debounceTimer.Stop();
        }

        private void WinEventProc(
            IntPtr hWinEventHook,
            uint @event,
            IntPtr hwnd,
            int idObject,
            int idChild,
            uint dwEventThread,
            uint dwmsEventTime)
        {
            if (@event != EVENT_SYSTEM_FOREGROUND || idObject != OBJID_WINDOW || idChild != CHILDID_SELF)
            {
                return;
            }

            uint pid = 0;
            var threadId = GetWindowThreadProcessId(hwnd, out pid);
            if (threadId == 0 || pid == 0)
            {
                return;
            }

            lock (_sync)
            {
                _pendingPid = (int)pid;
                _pendingHwnd = hwnd;
                _debounceTimer.Stop();
                _debounceTimer.Start();
            }
        }

        private void DebounceElapsed(object? sender, System.Timers.ElapsedEventArgs e)
        {
            int pid;
            IntPtr hwnd;
            lock (_sync)
            {
                pid = _pendingPid;
                hwnd = _pendingHwnd;
                _pendingPid = -1;
                _pendingHwnd = IntPtr.Zero;
            }

            if (pid == -1)
            {
                return;
            }

            // Fire event if PID changed OR if window handle changed (same-process window switch)
            if (pid == _lastPid && hwnd == _lastHwnd)
            {
                return;
            }

            var previous = _lastPid;
            _lastPid = pid;
            _lastHwnd = hwnd;
            var title = GetWindowTitleSafe(hwnd);
            ForegroundChanged?.Invoke(this, new ForegroundChangedEventArgs(previous, pid, hwnd, DateTimeOffset.UtcNow, title));
        }

        public void Dispose()
        {
            Stop();
            _debounceTimer.Dispose();
        }

        private static string? GetWindowTitleSafe(IntPtr hwnd)
        {
            try
            {
                var length = GetWindowTextLength(hwnd);
                if (length <= 0)
                {
                    return null;
                }

                var sb = new System.Text.StringBuilder(length + 1);
                if (GetWindowText(hwnd, sb, sb.Capacity) > 0)
                {
                    return sb.ToString();
                }
            }
            catch
            {
                // ignore
            }

            return null;
        }
    }
}

