    public partial class MainForm
    {
        private AppController? _appController;
        private PauseOnUnfocusSettings? _pauseSettings;
        private BrowserCoordinator? _browserCoordinator;

        private CheckBox? _pauseOnUnfocusCheckbox;
        private CheckBox? _autoPlaySpotifyCheckbox;
        private TextBox? _autoPlayAppTextBox;
        private NumericUpDown? _pauseCooldownNumeric;
        private GroupBox? _pauseSettingsGroupBox;
        private Icon? _trayBaseIcon;

        private void InitializePauseOnUnfocus()
        {
            _pauseSettings = new PauseOnUnfocusSettings();
            _pauseSettings.Load();

            // Start the browser coordinator for cross-profile extension communication
            _browserCoordinator = new BrowserCoordinator();
            _browserCoordinator.Start();
            LoggingEngine.LogLine("[PauseOnUnfocus] BrowserCoordinator started for extension communication",
                category: LoggingEngine.LogCategory.MediaControl);

            if (m_volumeMixer == null)
            {
                LoggingEngine.LogLine("[PauseOnUnfocus] VolumeMixer not initialized, skipping AppController init",
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                return;
            }

            var autoPlaySpotify = Properties.Settings.Default.AutoPlaySpotify;
            var autoPlayAppName = Properties.Settings.Default.AutoPlayAppName;

            _appController = new AppController(
                m_volumeMixer,
                _pauseSettings.AudibilityThreshold,
                null,
                GetNeverPauseList,
                autoPlaySpotify,
                autoPlayAppName,
                _pauseSettings.PauseCooldownMs,
                () => _browserCoordinator?.IsAnyTabPlaying ?? false);

            _appController.Enabled = _pauseSettings.Enabled;

            // Ensure autoplay monitor starts even when Pause on Unfocus is disabled
            // so Spotify can resume on startup when idle.
            if (autoPlaySpotify)
            {
                _appController.AutoPlaySpotify = true;
            }

            if (_pauseSettings.Enabled)
            {
                _appController.Start();
            }

            _trayBaseIcon ??= TrayIcon?.Icon;
            SetupPauseOnUnfocusTrayMenu();
            SetupPauseOnUnfocusUIPanel();
            SetupAutoPlayListUI();
            UpdateTrayIconPauseState();

            LoggingEngine.LogLine($"[PauseOnUnfocus] Initialized (Enabled={_pauseSettings.Enabled}, Mode={_pauseSettings.Mode})",
                category: LoggingEngine.LogCategory.General);
        }

        private void SetupPauseOnUnfocusUIPanel()
        {
            if (_pauseSettings == null)
            {
                return;
            }

            // Create a compact panel for audio control options
            // Add to LogTextBox's parent area (below log) for better visibility
            _pauseSettingsGroupBox = new GroupBox
            {
                Text = "🔊 Audio Control",
                Dock = DockStyle.Bottom,
                Height = 140,
                Padding = new Padding(3)
            };

            var innerPanel = new FlowLayoutPanel
            {
                Dock = DockStyle.Fill,
                FlowDirection = FlowDirection.TopDown,
                WrapContents = false,
                AutoSize = false
            };

            // Enable pause checkbox
            _pauseOnUnfocusCheckbox = new CheckBox
            {
                Text = "Enable Pause on Unfocus",
                Checked = _pauseSettings.Enabled,
                AutoSize = true,
                Margin = new Padding(3, 2, 3, 2)
            };
            _pauseOnUnfocusCheckbox.CheckedChanged += (s, e) =>
            {
                OnPauseOnUnfocusToggled(_pauseOnUnfocusCheckbox.Checked);
            };

            // Auto-play app checkbox
            _autoPlaySpotifyCheckbox = new CheckBox
            {
                Text = "Enable Auto-play when idle",
                Checked = Properties.Settings.Default.AutoPlaySpotify,
                AutoSize = true,
                Margin = new Padding(3, 2, 3, 2)
            };
            _autoPlaySpotifyCheckbox.CheckedChanged += (s, e) =>
            {
                OnAutoPlaySpotifyToggled(_autoPlaySpotifyCheckbox.Checked);
            };

            // Cooldown input
            _pauseCooldownNumeric = new NumericUpDown
            {
                Minimum = 0,
                Maximum = 600000,
                Increment = 100,
                Value = Math.Max(_pauseSettings.PauseCooldownMs, 0),
                Width = 120,
                Margin = new Padding(3, 2, 3, 2)
            };
            _pauseCooldownNumeric.ValueChanged += (s, e) =>
            {
                OnPauseCooldownChanged((int)_pauseCooldownNumeric.Value);
            };

            var cooldownLabel = new Label
            {
                Text = "Cooldown (ms):",
                AutoSize = true,
                Margin = new Padding(3, 6, 3, 2)
            };

            innerPanel.Controls.Add(_pauseOnUnfocusCheckbox);
            innerPanel.Controls.Add(_autoPlaySpotifyCheckbox);
            innerPanel.Controls.Add(cooldownLabel);
            innerPanel.Controls.Add(_pauseCooldownNumeric);

            _pauseSettingsGroupBox.Controls.Add(innerPanel);

            // Add to the main form's panel1 (bottom docked)
            if (panel1 != null)
            {
                panel1.Controls.Add(_pauseSettingsGroupBox);
                _pauseSettingsGroupBox.BringToFront();
            }
        }

        private void SetupPauseOnUnfocusTrayMenu()
        {
            if (_pauseSettings == null || TrayContextMenu == null)
            {
                return;
            }

            var enableToggle = TrayMenuExtensions.CreateEnableToggle(
                _pauseSettings.Enabled,
                OnPauseOnUnfocusToggled);

            // Insert before the separator
            var insertIndex = Math.Max(0, TrayContextMenu.Items.Count - 2);
            TrayContextMenu.Items.Insert(insertIndex, new ToolStripSeparator());
            TrayContextMenu.Items.Insert(insertIndex + 1, enableToggle);
        }

        private void OnPauseOnUnfocusToggled(bool enabled)
        {
            if (_pauseSettings == null || _appController == null)
            {
                return;
            }

            _pauseSettings.Enabled = enabled;
            _appController.Enabled = enabled;

            if (enabled)
            {
                _appController.Start();
                LoggingEngine.LogLine("[PauseOnUnfocus] Enabled", category: LoggingEngine.LogCategory.General);
            }
            else
            {
                _appController.Stop();
                LoggingEngine.LogLine("[PauseOnUnfocus] Disabled", category: LoggingEngine.LogCategory.General);
            }

            _pauseSettings.Save();
            UpdateTrayIconPauseState();
        }

        private void OnAutoPlaySpotifyToggled(bool enabled)
        {
            Properties.Settings.Default.AutoPlaySpotify = enabled;

            if (_appController != null)
            {
                _appController.AutoPlaySpotify = enabled;
            }

            LoggingEngine.LogLine($"[AutoPlay] {(enabled ? "Enabled" : "Disabled")} for {Properties.Settings.Default.AutoPlayAppName}",
                category: LoggingEngine.LogCategory.General);
        }

        private void OnAutoPlayAppNameChanged(string appName)
        {
            Properties.Settings.Default.AutoPlayAppName = appName;

            if (_appController != null)
            {
                _appController.AutoPlayAppName = appName;
            }

            LoggingEngine.LogLine($"[AutoPlay] App changed to: {appName}",
                category: LoggingEngine.LogCategory.General);
        }

        private void OnPauseCooldownChanged(int cooldownMs)
        {
            if (_pauseSettings == null)
            {
                return;
            }

            _pauseSettings.PauseCooldownMs = cooldownMs;

            if (_appController != null)
            {
                _appController.PauseCooldownMs = cooldownMs;
            }

            _pauseSettings.Save();
        }

        private void CleanupPauseOnUnfocus()
        {
            _appController?.Stop();
            _appController?.Dispose();
            _appController = null;
        }

        private IEnumerable<string> GetNeverPauseList()
        {
            // Reuse the same canonical never-mute set for pause
            return GetNeverMuteSet();
        }

        private void UpdateTrayIconPauseState()
        {
            if (TrayIcon == null)
            {
                return;
            }

            var isEnabled = _pauseSettings?.Enabled ?? false;
            var stateLabel = isEnabled ? "Active" : "Disabled";
            TrayIcon.Text = $"BGMuter (Pause: {stateLabel})";

            if (_trayBaseIcon != null)
            {
                TrayIcon.Icon = isEnabled ? _trayBaseIcon : SystemIcons.Exclamation;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using WinBGMuter.Abstractions;
using Windows.Media.Control;

namespace WinBGMuter.Media
{
    internal sealed class GsmtcMediaController : IMediaController
    {
        private GlobalSystemMediaTransportControlsSessionManager? _manager;

        public async Task<IReadOnlyList<MediaSessionInfo>> ListSessionsAsync(CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            await EnsureManagerAsync().ConfigureAwait(false);

            if (_manager == null)
            {
                return Array.Empty<MediaSessionInfo>();
            }

            var sessions = _manager.GetSessions();
            var result = new List<MediaSessionInfo>(sessions.Count);

            foreach (var s in sessions)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var key = BuildKey(s);
                var info = s.GetPlaybackInfo();
                var state = MapState(info?.PlaybackStatus);
                result.Add(new MediaSessionInfo(
                    key,
                    displayName: s.SourceAppUserModelId,
                    appId: s.SourceAppUserModelId,
                    playbackState: state,
                    lastUpdated: info?.Controls?.IsPauseEnabled == true || info?.Controls?.IsPlayEnabled == true
                        ? DateTimeOffset.UtcNow
                        : DateTimeOffset.MinValue));
            }

            return result;
        }

        public async Task<MediaControlResult> TryPauseAsync(MediaSessionKey session, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            var s = await GetSessionAsync(session, cancellationToken).ConfigureAwait(false);
            if (s == null)
            {
                LoggingEngine.LogLine($"[GSMTC] TryPauseAsync: Session not found for {session.Id}",
                    category: LoggingEngine.LogCategory.MediaControl,
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                return MediaControlResult.NotSupported;
            }

            try
            {
                var playbackInfo = s.GetPlaybackInfo();
                if (playbackInfo?.Controls?.IsPauseEnabled != true)
                {
                    LoggingEngine.LogLine($"[GSMTC] TryPauseAsync: Pause not supported for {session.Id}",
                        category: LoggingEngine.LogCategory.MediaControl,
                        loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                    return MediaControlResult.NotSupported;
                }

                bool success = await s.TryPauseAsync();
                LoggingEngine.LogLine($"[GSMTC] TryPauseAsync: {session.Id} -> {(success ? "SUCCESS" : "FAILED")}",
                    category: LoggingEngine.LogCategory.MediaControl);
                return success ? MediaControlResult.Success : MediaControlResult.Failed;
            }
            catch (Exception ex)
            {
                LoggingEngine.LogLine($"[GSMTC] TryPauseAsync exception: {ex.Message}",
                    category: LoggingEngine.LogCategory.MediaControl,
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_ERROR);
                return MediaControlResult.Failed;
            }
        }

        public async Task<MediaControlResult> TryPlayAsync(MediaSessionKey session, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            var s = await GetSessionAsync(session, cancellationToken).ConfigureAwait(false);
            if (s == null)
            {
                LoggingEngine.LogLine($"[GSMTC] TryPlayAsync: Session not found for {session.Id}",
                    category: LoggingEngine.LogCategory.MediaControl,
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                return MediaControlResult.NotSupported;
            }

            try
            {
                var playbackInfo = s.GetPlaybackInfo();
                if (playbackInfo?.Controls?.IsPlayEnabled != true)
                {
                    LoggingEngine.LogLine($"[GSMTC] TryPlayAsync: Play not supported for {session.Id}",
                        category: LoggingEngine.LogCategory.MediaControl,
                        loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_WARNING);
                    return MediaControlResult.NotSupported;
                }

                bool success = await s.TryPlayAsync();
                LoggingEngine.LogLine($"[GSMTC] TryPlayAsync: {session.Id} -> {(success ? "SUCCESS" : "FAILED")}",
                    category: LoggingEngine.LogCategory.MediaControl);
                return success ? MediaControlResult.Success : MediaControlResult.Failed;
            }
            catch (Exception ex)
            {
                LoggingEngine.LogLine($"[GSMTC] TryPlayAsync exception: {ex.Message}",
                    category: LoggingEngine.LogCategory.MediaControl,
                    loglevel: LoggingEngine.LOG_LEVEL_TYPE.LOG_ERROR);
                return MediaControlResult.Failed;
            }
        }

        private async Task EnsureManagerAsync()
        {
            if (_manager != null)
            {
                return;
            }

            _manager = await GlobalSystemMediaTransportControlsSessionManager.RequestAsync();
        }

        private static MediaSessionKey BuildKey(GlobalSystemMediaTransportControlsSession session)
        {
            var appId = session.SourceAppUserModelId;
            if (!string.IsNullOrWhiteSpace(appId))
            {
                return new MediaSessionKey(appId, appId);
            }

            // Fallback for sessions without AUMID: use hash to enable lookup within this process.
            var fallbackId = session.GetHashCode().ToString("X");
            return new MediaSessionKey(fallbackId, null);
        }

        private async Task<GlobalSystemMediaTransportControlsSession?> GetSessionAsync(MediaSessionKey key, CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            await EnsureManagerAsync().ConfigureAwait(false);

            if (_manager == null)
            {
                return null;
            }

            var sessions = _manager.GetSessions();
            if (!string.IsNullOrWhiteSpace(key.SourceAppUserModelId))
            {
                return sessions.FirstOrDefault(s => (s.SourceAppUserModelId ?? string.Empty) == key.SourceAppUserModelId);
            }

            var keyId = key.Id ?? string.Empty;
            var aumidMatch = sessions.FirstOrDefault(s => (s.SourceAppUserModelId ?? string.Empty) == keyId);
            if (aumidMatch != null)
            {
                return aumidMatch;
            }

            return sessions.FirstOrDefault(s =>
                string.IsNullOrWhiteSpace(s.SourceAppUserModelId) &&
                s.GetHashCode().ToString("X") == keyId);
        }

        private static MediaPlaybackState MapState(GlobalSystemMediaTransportControlsSessionPlaybackStatus? status)
        {
            return status switch
            {
                GlobalSystemMediaTransportControlsSessionPlaybackStatus.Playing => MediaPlaybackState.Playing,
                GlobalSystemMediaTransportControlsSessionPlaybackStatus.Paused => MediaPlaybackState.Paused,
                GlobalSystemMediaTransportControlsSessionPlaybackStatus.Stopped => MediaPlaybackState.Stopped,
                _ => MediaPlaybackState.Unknown
            };
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using WinBGMuter.Abstractions;

namespace WinBGMuter.Media
{
    internal sealed class SessionResolver
    {
        private readonly IMediaController _mediaController;
        private readonly IReadOnlyDictionary<string, string> _processNameToSessionHint;

        public SessionResolver(IMediaController mediaController, IReadOnlyDictionary<string, string>? processNameToSessionHint = null)
        {
            _mediaController = mediaController;
            _processNameToSessionHint = processNameToSessionHint ?? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        }

        public async Task<SessionResolution> ResolveAsync(string processName, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();

            var sessions = await _mediaController.ListSessionsAsync(cancellationToken).ConfigureAwait(false);

            LoggingEngine.LogLine($"[SessionResolver] Resolving for process '{processName}', found {sessions.Count} sessions",
                category: LoggingEngine.LogCategory.MediaControl);

            foreach (var s in sessions)
            {
                LoggingEngine.LogLine($"[SessionResolver] Session: {s.AppId} ({s.Key.Id}), State: {s.PlaybackState}",
                    category: LoggingEngine.LogCategory.MediaControl);
            }

            if (sessions.Count == 0)
            {
                return SessionResolution.NotFound;
            }

            // 1) Try to match by process name (case-insensitive partial match)
            var processMatch = sessions.FirstOrDefault(s =>
                !string.IsNullOrEmpty(s.AppId) &&
                (s.AppId.Contains(processName, StringComparison.OrdinalIgnoreCase) ||
                 processName.Contains(s.AppId.Split('.').LastOrDefault() ?? "", StringComparison.OrdinalIgnoreCase)));

            if (processMatch != null)
            {
                LoggingEngine.LogLine($"[SessionResolver] Matched by process name: {processMatch.AppId}",
                    category: LoggingEngine.LogCategory.MediaControl);
                return SessionResolution.Success(processMatch.Key);
            }

            // 2) exact map by known app identifiers / process name hint
            if (_processNameToSessionHint.TryGetValue(processName, out var hintedAppId))
            {
                var match = sessions.FirstOrDefault(s =>
                    string.Equals(s.AppId, hintedAppId, StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(s.Key.Id, hintedAppId, StringComparison.OrdinalIgnoreCase));

                if (match != null)
                {
                    LoggingEngine.LogLine($"[SessionResolver] Matched by hint: {match.AppId}",
                        category: LoggingEngine.LogCategory.MediaControl);
                    return SessionResolution.Success(match.Key);
                }
            }

            // 3) No match found - do NOT fallback to unrelated sessions!
            // Only pause apps that have their own media session
            LoggingEngine.LogLine($"[SessionResolver] No matching session for '{processName}' - skipping (not a media app)",
                category: LoggingEngine.LogCategory.MediaControl);
            return SessionResolution.NotFound;
        }
    }

    internal readonly struct SessionResolution
    {
        private SessionResolution(MediaSessionKey? session, SessionResolutionStatus status)
        {
            Session = session;
            Status = status;
        }

        public MediaSessionKey? Session { get; }
        public SessionResolutionStatus Status { get; }

        public static SessionResolution Success(MediaSessionKey session) => new(session, SessionResolutionStatus.Success);
        public static SessionResolution NotFound => new(null, SessionResolutionStatus.NotFound);
        public static SessionResolution Ambiguous => new(null, SessionResolutionStatus.Ambiguous);
    }

    internal enum SessionResolutionStatus
    {
        Success,
        NotFound,
        Ambiguous
    }
}

using System;
using System.Runtime.InteropServices;

namespace WinBGMuter.Media
{
    /// <summary>
    /// Sends media commands (play, pause, stop) to specific windows using WM_APPCOMMAND.
    /// This enables per-window media control, unlike GSMTC which is app-level.
    /// </summary>
    internal static class Win32MediaCommandController
    {
        private const int WM_APPCOMMAND = 0x0319;

        // Media command codes (shifted left by 16 bits for lParam)
        private const int APPCOMMAND_MEDIA_PLAY = 46;
        private const int APPCOMMAND_MEDIA_PAUSE = 47;
        private const int APPCOMMAND_MEDIA_PLAY_PAUSE = 14;
        private const int APPCOMMAND_MEDIA_STOP = 13;
        private const int APPCOMMAND_MEDIA_NEXTTRACK = 11;
        private const int APPCOMMAND_MEDIA_PREVIOUSTRACK = 12;

        // For simulating key presses
        private const byte VK_MEDIA_PLAY_PAUSE = 0xB3;
        private const int KEYEVENTF_EXTENDEDKEY = 0x0001;
        private const int KEYEVENTF_KEYUP = 0x0002;

        [DllImport("user32.dll", SetLastError = true)]
        private static extern IntPtr SendMessage(IntPtr hWnd, int Msg, IntPtr wParam, IntPtr lParam);

        [DllImport("user32.dll", SetLastError = true)]
        private static extern bool PostMessage(IntPtr hWnd, int Msg, IntPtr wParam, IntPtr lParam);

        [DllImport("user32.dll", SetLastError = true)]
        private static extern IntPtr GetAncestor(IntPtr hwnd, uint gaFlags);

        [DllImport("user32.dll", SetLastError = true)]
        private static extern IntPtr GetForegroundWindow();

        [DllImport("user32.dll", SetLastError = true)]
        private static extern bool SetForegroundWindow(IntPtr hWnd);

        [DllImport("user32.dll", SetLastError = true)]
        private static extern void keybd_event(byte bVk, byte bScan, int dwFlags, int dwExtraInfo);

        private const uint GA_ROOT = 2;

        /// <summary>
        /// Sends a pause command to the specified window.
        /// </summary>
        public static bool SendPause(IntPtr hWnd)
        {
            if (hWnd == IntPtr.Zero)
            {
                return false;
            }

            var lParam = MakeCommandLParam(APPCOMMAND_MEDIA_PAUSE);
            var result = SendMessage(hWnd, WM_APPCOMMAND, hWnd, lParam);

            LoggingEngine.LogLine($"[Win32Media] SendPause to {hWnd} -> result={result}",
                category: LoggingEngine.LogCategory.MediaControl);

            return true;
        }

        /// <summary>
        /// Sends a play command to the specified window.
        /// </summary>
        public static bool SendPlay(IntPtr hWnd)
        {
            if (hWnd == IntPtr.Zero)
            {
                return false;
            }

            var lParam = MakeCommandLParam(APPCOMMAND_MEDIA_PLAY);
            var result = SendMessage(hWnd, WM_APPCOMMAND, hWnd, lParam);

            LoggingEngine.LogLine($"[Win32Media] SendPlay to {hWnd} -> result={result}",
                category: LoggingEngine.LogCategory.MediaControl);

            return true;
        }

        /// <summary>
        /// Sends a play/pause toggle command to the specified window.
        /// </summary>
        public static bool SendPlayPauseToggle(IntPtr hWnd)
        {
            if (hWnd == IntPtr.Zero)
            {
                return false;
            }

            var lParam = MakeCommandLParam(APPCOMMAND_MEDIA_PLAY_PAUSE);
            var result = SendMessage(hWnd, WM_APPCOMMAND, hWnd, lParam);

            LoggingEngine.LogLine($"[Win32Media] SendPlayPauseToggle to {hWnd} -> result={result}",
                category: LoggingEngine.LogCategory.MediaControl);

            return true;
        }

        /// <summary>
        /// Sends a stop command to the specified window.
        /// </summary>
        public static bool SendStop(IntPtr hWnd)
        {
            if (hWnd == IntPtr.Zero)
            {
                return false;
            }

            var lParam = MakeCommandLParam(APPCOMMAND_MEDIA_STOP);
            var result = SendMessage(hWnd, WM_APPCOMMAND, hWnd, lParam);

            LoggingEngine.LogLine($"[Win32Media] SendStop to {hWnd} -> result={result}",
                category: LoggingEngine.LogCategory.MediaControl);

            return true;
        }

        /// <summary>
        /// Posts a pause command asynchronously to the specified window.
        /// Tries multiple approaches: direct window, root ancestor, and keyboard simulation.
        /// </summary>
        public static bool PostPause(IntPtr hWnd)
        {
            if (hWnd == IntPtr.Zero)
            {
                return false;
            }

            // Try 1: Send to the root ancestor window (works better for browsers)
            var rootHwnd = GetAncestor(hWnd, GA_ROOT);
            if (rootHwnd != IntPtr.Zero && rootHwnd != hWnd)
            {
                var lParam = MakeCommandLParam(APPCOMMAND_MEDIA_PAUSE);
                SendMessage(rootHwnd, WM_APPCOMMAND, rootHwnd, lParam);
                LoggingEngine.LogLine($"[Win32Media] SendPause to root {rootHwnd} (from {hWnd})",
                    category: LoggingEngine.LogCategory.MediaControl);
            }

            // Try 2: Post to the window itself
            var lParam2 = MakeCommandLParam(APPCOMMAND_MEDIA_PAUSE);
            var result = PostMessage(hWnd, WM_APPCOMMAND, hWnd, lParam2);

            LoggingEngine.LogLine($"[Win32Media] PostPause to {hWnd} -> success={result}",
                category: LoggingEngine.LogCategory.MediaControl);

            return result;
        }

        /// <summary>
        /// Sends a global media play/pause key press using keyboard simulation.
        /// This pauses whatever media is currently active system-wide.
        /// </summary>
        public static void SendGlobalMediaPlayPause()
        {
            keybd_event(VK_MEDIA_PLAY_PAUSE, 0, KEYEVENTF_EXTENDEDKEY, 0);
            keybd_event(VK_MEDIA_PLAY_PAUSE, 0, KEYEVENTF_EXTENDEDKEY | KEYEVENTF_KEYUP, 0);

            LoggingEngine.LogLine($"[Win32Media] Sent global Media Play/Pause key",
                category: LoggingEngine.LogCategory.MediaControl);
        }

        private static IntPtr MakeCommandLParam(int command)
        {
            // lParam format: command << 16
            return new IntPtr(command << 16);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using WinBGMuter.Abstractions;

namespace WinBGMuter.Policy
{
    internal sealed class ActionPolicyEngine : IActionPolicy
    {
        private readonly PolicyListMode _listMode;
        private readonly HashSet<string> _includedProcesses;
        private readonly HashSet<string> _excludedProcesses;
        private readonly int _selfPid;

        public ActionPolicyEngine(
            PolicyListMode listMode = PolicyListMode.Blacklist,
            IEnumerable<string>? includedProcesses = null,
            IEnumerable<string>? excludedProcesses = null)
        {
            _listMode = listMode;
            _includedProcesses = new HashSet<string>(includedProcesses ?? Enumerable.Empty<string>(), StringComparer.OrdinalIgnoreCase);
            _excludedProcesses = new HashSet<string>(excludedProcesses ?? Enumerable.Empty<string>(), StringComparer.OrdinalIgnoreCase);
            _selfPid = Environment.ProcessId;
        }

        public PolicyDecision Evaluate(int foregroundPid, IReadOnlyList<int> audiblePids, string? foregroundProcessName = null)
        {
            var toPause = new List<int>();

            foreach (var pid in audiblePids)
            {
                if (pid == foregroundPid || pid == _selfPid)
                {
                    continue;
                }

                if (!ShouldActOn(pid, null))
                {
                    continue;
                }

                toPause.Add(pid);
            }

            return new PolicyDecision(toPause);
        }

        private bool ShouldActOn(int pid, string? processName)
        {
            if (processName == null)
            {
                try
                {
                    processName = System.Diagnostics.Process.GetProcessById(pid).ProcessName;
                }
                catch
                {
                    return false;
                }
            }

            return _listMode switch
            {
                PolicyListMode.Whitelist => _includedProcesses.Contains(processName),
                PolicyListMode.Blacklist => !_excludedProcesses.Contains(processName),
                _ => true
            };
        }
    }
}

